// The nonce is generated by Proxy, never accepted from a client header.
export function contentSecurityPolicy(nonce:string,development=false){
 if(!/^[A-Za-z0-9+/_=-]{20,128}$/.test(nonce))throw new Error('Invalid CSP nonce');
 return `default-src 'self'; script-src 'self' 'nonce-${nonce}' 'strict-dynamic'${development?" 'unsafe-eval'":''}; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; font-src 'self'; connect-src 'self'; worker-src 'self' blob:; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'`;
}
